// chatbotData.js

const chatbotData = {
  "Menu Principal": {
    "1": { texto: "Acesso à conta", next: "Acesso à conta" },
    "2": { texto: "Cursos e Conteúdo", next: "Cursos e Conteúdo" },
    "3": { texto: "Pagamentos e Certificados", next: "Pagamentos e Certificados" }
  },
  "Acesso à conta": {
    "1": { texto: "Esqueci minha senha", resposta: "Clique em 'Esqueci minha senha' na tela de login." },
    "2": { texto: "Não consigo acessar meu curso", resposta: "Verifique se o pagamento está confirmado e tente novamente." },
    "3": { texto: "Alterar e-mail ou usuário", resposta: "Vá em 'Minha Conta' e atualize suas informações." }
  },
  "Cursos e Conteúdo": {
    "1": { texto: "Posso baixar as aulas?", resposta: "Os vídeos só podem ser assistidos online por segurança." },
    "2": { texto: "Até quando tenho acesso?", resposta: "Você terá acesso por 12 meses a partir da compra." },
    "3": { texto: "Onde vejo meu progresso?", resposta: "Seu progresso fica disponível na aba 'Meu Painel'." }
  },
  "Pagamentos e Certificados": {
    "1": { texto: "Quais formas de pagamento são aceitas?", resposta: "Aceitamos cartão de crédito, PIX e boleto." },
    "2": { texto: "O curso tem certificado?", resposta: "Sim! Após concluir todas as aulas e atividades obrigatórias." },
    "3": { texto: "Preciso pagar para emitir o certificado?", resposta: "Não, o certificado já está incluso no valor do curso." }
  }
};

export default chatbotData;
